<script setup lang="ts">
import {tr} from '../../i18n/index.ts';
import {computed} from 'vue';
import ScientificPlot from '../../components/ScientificPlot.vue';
import {visibleAmplitude,visibleF0Range} from './display.ts';
import type {EggPreviewData,EggTaskConfig} from '../../platform/research.ts';
const props=defineProps<{data?:EggPreviewData;psd?:string;config:EggTaskConfig}>();const emit=defineEmits<{seek:[time:number];gesture:[area:'main'|'micro',kind:'zoom'|'pan',value:number]}>();
const range=computed<[number,number]>(()=>[props.config.roi_start??0,props.config.roi_end??.5]);
const microRange=computed<[number,number]>(()=>[-(props.config.micro_width_ms??50)/2,(props.config.micro_width_ms??50)/2]);
const cursor=computed(()=>props.data?[{time:props.config.micro_center??props.data.micro_center,label:tr('modules.egg-analysis.microscopic_centre'),color:'var(--danger)'}]:[]);
const microHighlight=computed<[number,number]|undefined>(()=>{if(!props.data)return;const center=props.config.micro_center??props.data.micro_center,half=(props.config.micro_width_ms??50)/2000;return [center-half,center+half];});
const markers=computed(()=>[...(props.data?.gci??[]).map(time=>({time:(time-(props.config.micro_center??props.data!.micro_center))*1000,label:'GCI'})),...(props.data?.goi??[]).map(time=>({time:(time-(props.config.micro_center??props.data!.micro_center))*1000,label:'GOI',dashed:true})),{time:0,label:tr('modules.egg-analysis.microscopic_centre_0_ms'),color:'var(--danger)'}]);
const trace=(key:'cq'|'sq'|'praat'|'gci_f0'|'reaper',label:string,color:string,right=false)=>({...(props.data?.[key]??{times:[],values:[]}),label,color,right,points:true});
const micro=(key:'audio'|'egg',label:string,color:string)=>({times:(props.data?.[key].times??[]).map(t=>(t-(props.config.micro_center??props.data!.micro_center))*1000),values:props.data?.[key].values??[],label,color});
const f0Range=computed(()=>visibleF0Range([...(props.config.keep_praat_f0&&props.data?[props.data.praat]:[]),...(props.config.keep_gci_f0&&props.data?[props.data.gci_f0]:[]),...(props.config.keep_reaper_f0&&props.data?.reaper?[props.data.reaper]:[])],...range.value));
const amplitude=(key:'audio'|'egg')=>{const trace=micro(key,'','');return visibleAmplitude(trace.times,trace.values,...microRange.value);};
</script>
<template><div class="egg-four-plots" :title="tr('modules.egg-analysis.cq_repeated_filtering_of_processed_100_ms_microscopic_display')">
<section class="egg-plot cq-pane"><header><h2>CQ / SQ</h2><small>{{tr('modules.egg-analysis.click_to_position_wheel_to_zoom_drag_to_pan')}}</small></header><ScientificPlot fill :height="240" :show-legend="false" :highlight="microHighlight" interactive wheel-zoom live-pan :axis-label-width="6" :markers="cursor" @zoom="emit('gesture','main','zoom',$event)" @pan="emit('gesture','main','pan',$event)" :title="tr('modules.egg-analysis.cq_and_sq_dual_axis_plot')" :x="range" :y="[0,1]" :right="[-1.1,1.1]" unit="CQ" right-unit="SQ" :empty="!data" :traces="[trace('cq','CQ','var(--wave)'),trace('sq','SQ','var(--teal)',true)]" @seek="emit('seek',$event)"/></section>
<section class="egg-plot audio-pane"><header><h2>{{tr('modules.egg-analysis.audio_microscopic')}} <span class="micro-width">{{(config.micro_width_ms??50).toFixed(2)}} ms</span></h2><small>{{data?(config.micro_center??data.micro_center).toFixed(4)+' s':tr('modules.egg-analysis.no_position_selected')}} {{tr('modules.egg-analysis.relative_time')}}<span v-if="(data?.micro_sample_stride??1)>1"> {{tr('modules.egg-analysis.every')}} {{data?.micro_sample_stride}} {{tr('modules.egg-analysis.points_shown_as_one')}}</span></small></header><ScientificPlot fill :height="240" :show-legend="false" interactive wheel-zoom live-pan @zoom="emit('gesture','micro','zoom',$event)" @pan="emit('gesture','micro','pan',$event)" :title="tr('modules.egg-analysis.audio_microscopic_waveform_and_events')" :x="microRange" :y="amplitude('audio')" :unit="tr('modules.egg-analysis.normalized_amplitude')" x-unit="ms" :empty="!data" :markers="markers" :traces="[micro('audio',tr('modules.egg-analysis.normalized_audio'),'var(--waveform-color,var(--wave))')]"/></section>
<section class="egg-plot spec-pane"><header><h2>{{tr('modules.egg-analysis.spectrogram_f0')}}</h2><small>{{tr('modules.egg-analysis.psd_frequency_on_left_f0_on_right')}}</small></header><ScientificPlot fill :height="240" :show-legend="!!(config.keep_praat_f0||config.keep_gci_f0||config.keep_reaper_f0)" :highlight="microHighlight" interactive wheel-zoom live-pan @zoom="emit('gesture','main','zoom',$event)" @pan="emit('gesture','main','pan',$event)" :title="tr('modules.egg-analysis.egg_audio_spectrogram_and_f0')" :axis-label-width="6" :markers="[...cursor,...(data?.movement??[]).map(([time,label])=>({time,label}))]" :x="range" :y="[0,5000]" :right="f0Range" reserve-right-axis unit="Hz" :right-unit="f0Range?'F0 Hz':undefined" :empty="!data" :raster="data&&psd?{url:psd,extent:data.spectral_extent}:undefined" :traces="[...(config.keep_praat_f0?[trace('praat','Praat','var(--violet)',true)]:[]),...(config.keep_gci_f0?[trace('gci_f0','GCI F0','var(--danger)',true)]:[]),...(config.keep_reaper_f0?[trace('reaper','REAPER F0','var(--teal)',true)]:[])]" @seek="emit('seek',$event)"/></section>
<section class="egg-plot egg-pane"><header><h2>{{tr('modules.egg-analysis.egg_microscopic')}} <span class="micro-width">{{(config.micro_width_ms??50).toFixed(2)}} ms</span></h2><slot name="filter"/></header><ScientificPlot fill :height="240" :show-legend="false" interactive wheel-zoom live-pan @zoom="emit('gesture','micro','zoom',$event)" @pan="emit('gesture','micro','pan',$event)" :title="tr('modules.egg-analysis.egg_microscopic_waveform_and_events')" :x="microRange" :y="amplitude('egg')" :unit="tr('modules.egg-analysis.normalized_amplitude')" x-unit="ms" :empty="!data" :markers="markers" :traces="[micro('egg',config.signal_mode==='raw'?tr('modules.egg-analysis.raw_egg'):tr('modules.egg-analysis.filtered_egg'),'var(--teal)')]"/></section>
</div></template>
<style scoped>
.egg-four-plots{display:grid;grid-template-columns:1fr 1fr;gap:10px;min-width:0}.egg-plot{min-width:0;border:1px solid var(--border);border-radius:var(--radius);background:var(--panel);overflow:hidden}.egg-plot>header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:8px 12px 0;min-height:35px}.egg-plot>.hint{padding:0 12px 7px}.micro-width{font-weight:400;white-space:nowrap}@media(max-width:980px){.egg-four-plots{grid-template-columns:1fr}.audio-pane{grid-row:3}}
.egg-four-plots{height:100%;grid-template-rows:repeat(2,minmax(0,1fr))}.egg-plot{display:flex;flex-direction:column;min-height:0}.egg-plot :deep(.scientific-plot){flex:1;min-height:0}.egg-plot>header{flex:none}@media(max-width:980px){.egg-four-plots{grid-template-rows:repeat(4,minmax(240px,1fr))}}
</style>
